//! Source control host and tool marks (web `sourceControlIcon` / `VCS_ICONS`), one single-colour
//! layer per fill since Rune icons are masks. `None` layers take the foreground, like web's
//! `currentColor` marks. Path data is generated from the web SVGs.
use crate::theme::{AlphaMul, T};
use rune::{El, Icon, el, icon};

/// Web `SourceControlItemMark`: an 18px mark in a 20px box, with the status dot over its corner.
pub fn mark(kind: &str, dot: rune::Color, t: &T) -> Option<El> {
    let layers = layers(kind)?;
    let mut mark = el().size(20.0, 20.0);
    for (glyph, color) in layers {
        let color = color.and_then(rune::color::hex).unwrap_or(t.c.foreground.alpha_mul(0.8));
        mark = mark.child(icon(glyph, 18.0).color(color).absolute(1.0, 1.0));
    }
    let ring = el().size(12.0, 12.0).radius(6.0).fill(t.c.background).absolute(-4.0, -4.0);
    Some(mark.child(ring).child(el().size(8.0, 8.0).radius(4.0).fill(dot).absolute(-2.0, -2.0)))
}

